var grown=new GameObject{name="Pickable_Carrot"};var seed=new GameObject{name="carrot"};var piece=seed.Add(new Piece());seed.Add(new Plant{m_grownPrefabs=new[]{grown}});ZNetScene.instance.m_prefabs.Add(seed);
