Check(PlantHarness.SeedFor(ripe)==piece,"legacy grown crop resolves without Piece or Plant");
PlantHarness.AfterPick(ripe,player,true);Check(player.Planted==piece&&player.Paid==1,"one-shot harvest replants correct seed and pays once");
player.Planted=null;player.Paid=0;ripe.m_respawnTimeMinutes=10;PlantHarness.AfterPick(ripe,player,true);Check(player.Planted==null&&player.Paid==0,"regrowing forage is not replanted");
